public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (String str : strings) {
        if (str.length() > maxLength) {
            maxLength = str.length();
        }
    }

    boolean found = false;

    while (found == false) {
        found = true;
        for (String str : strings) {
            if (str.length() != maxLength) {
                continue;
            }

            String reversedStr = new StringBuilder(str).reverse().toString();
            if (!str.contains(reversedStr) && !reversedStr.contains(str)) {
                maxLength--;
                found = false;
                break;
            }
        }
    }

    return maxLength;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    int maxLength = 0;

    for (String str : strings) {
        for (String s : strings) {
            if (!str.equals(s)) {
                if (isSubstringOrInverse(str, s)) {
                    maxLength = Math.max(maxLength, str.length());
                }
            }
        }
    }

    return maxLength;
}

private boolean isSubstringOrInverse(String str, String s) {
    return s.contains(str) || s.contains(new StringBuilder(str).reverse().toString());
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxSubstringLength = 0;

    for (String str : strings) {
        if (str == null || str.isEmpty()) {
            continue;
        }

        Set<String> substrings = generateSubstrings(str);
        Set<String> reversedSubstrings = generateSubstrings(new StringBuilder(str).reverse().toString());

        for (String sub : substrings) {
            for (String revSub : reversedSubstrings) {
                if (anyStringContainsSubstring(strings, sub) || anyStringContainsSubstring(strings, revSub)) {
                    maxSubstringLength = Math.max(maxSubstringLength, sub.length());
                }
            }
        }
    }

    return maxSubstringLength;
}

private Set<String> generateSubstrings(String str) {
    Set<String> substrings = new HashSet<>();
    for (int i = 0; i < str.length(); i++) {
        for (int j = i + 1; j <= str.length(); j++) {
            substrings.add(str.substring(i, j));
        }
    }
    return substrings;
}

private boolean anyStringContainsSubstring(List<String> strings, String substring) {
    for (String str : strings) {
        if (str.contains(substring)) {
            return true;
        }
    }
    return false;
}

