    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                dfs(grid, i, j);
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != '@') {
        return;
    }

    grid[i][j] = '*'; // Mark as visited

    dfs(grid, i - 1, j); // Up
    dfs(grid, i + 1, j); // Down
    dfs(grid, i, j - 1); // Left
    dfs(grid, i, j + 1); // Right
}

