private static void markOilDeposits(char[][] grid, int i, int j, int rows, int cols) {
    if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] != '@') {
        return;
    }

    grid[i][j] = '#'; // Mark as visited

    markOilDeposits(grid, i - 1, j, rows, cols); // Up
    markOilDeposits(grid, i + 1, j, rows, cols); // Down
    markOilDeposits(grid, i, j - 1, rows, cols); // Left
    markOilDeposits(grid, i, j + 1, rows, cols); // Right
    markOilDeposits(grid, i - 1, j - 1, rows, cols); // Up-Left
    markOilDeposits(grid, i - 1, j + 1, rows, cols); // Up-Right
    markOilDeposits(grid, i + 1, j - 1, rows, cols); // Down-Left
    markOilDeposits(grid, i + 1, j + 1, rows, cols); // Down-Right
}

