public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check for invalid input
    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Create a graph to represent the maze
    boolean[][] graph = new boolean[n][n];
    for (int[] path : paths) {
        int u = path[0];
        int v = path[1];
        if (u >= 0 && u < n && v >= 0 && v < n) {
            graph[u][v] = true;
            graph[v][u] = true;
        }
    }

    // Check if the start and end coordinates are within the valid range
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Use BFS to check if there is a path from start to end
    boolean[] visited = new boolean[n];
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    visited[start[0]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int i = 0; i < n; i++) {
            if (graph[current[0]][i] && !visited[i]) {
                queue.add(new int[]{i, 0});
                visited[i] = true;
            }
        }
    }

    // If we exhaust the queue without finding a path, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Start and end coordinates must be 2D.");
    }

    boolean[][] graph = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 2) {
            throw new IllegalArgumentException("Path coordinates must be 2D.");
        }
        int from = path[0];
        int to = path[1];
        graph[from][to] = true;
        graph[to][from] = true; // Assuming the maze is undirected
    }

    boolean[] visited = new boolean[n];
    if (dfs(graph, visited, start[0], end[0])) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean dfs(boolean[][] graph, boolean[] visited, int current, int target) {
    if (current == target) {
        return true;
    }
    visited[current] = true;
    for (int i = 0; i < graph.length; i++) {
        if (graph[current][i] && !visited[i]) {
            if (dfs(graph, visited, i, target)) {
                return true;
            }
        }
    }
    visited[current] = false;
    return false;
}

