}

private static boolean canTravelMazeHelper(int n, int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x == endX && y == endY) {
        return true;
    }

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    for (int[] direction : directions) {
        int newX = x + direction[0];
