        if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
            visited[newX][newY] = true;
            for (int[] path : paths) {
                if (path[0] == x && path[1] == y && (path[2] == newX || path[2] == newY) && (path[3] == newY || path[3] == newX)) {
                    if (canTravelMazeHelper(n, newX, newY, endX, endY, paths, visited)) {
                        return true;
                    }
                }
            }
            visited[newX][newY] = false;
        }
    }

    return false;
}

