public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[] dp = new boolean[sum + 1];
    dp[0] = true;

    for (int num : nums) {
        for (int j = sum; j >= num; j--) {
            dp[j] = dp[j] || dp[j - num];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (dp[sum * i / n] && sum * i % n == 0) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    for (int x = 1; x <= n / 2; x++) {
        if (sum * x % n == 0) {
            Set<Integer> set = new HashSet<>();
            for (int i = 0; i < n; i++) {
                if (x == 1) {
                    if (nums[i] * n == sum * 1) {
                        return true;
                    }
                } else {
                    set.addAll(computeSum(nums, i + 1, n - 1, x - 1));
                    if (set.contains(sum * x - sum * (n - x))) {
                        return true;
                    }
                }
            }
        }
    }

    return false;
}

private Set<Integer> computeSum(int[] nums, int start, int end, int k) {
    Set<Integer> result = new HashSet<>();
    if (k == 1) {
        for (int i = start; i <= end; i++) {
            result.add(nums[i]);
        }
    } else {
        for (int i = start; i <= end; i++) {
            for (int num : computeSum(nums, i + 1, end, k - 1)) {
                result.add(nums[i] + num);
            }
        }
    }
    return result;
}

