        sum += num;
    }

    boolean[][] dp = new boolean[n + 1][sum + 1];
    dp[0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = sum; j >= nums[i - 1]; j--) {
            dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

