    }

    for (int i = 1; i <= n / 2; i++) {
        if (totalSum * i % n == 0) {
            if (hasSum(nums, i, totalSum * i / n, 0, 0)) {
                return true;
            }
        }
    }

    return false;
}

private boolean hasSum(int[] nums, int targetSize, long targetSum, int index, int currentSum) {
    if (targetSize == 0) {
        return currentSum == targetSum;
    }
    if (index == nums.length) {
        return false;
    }

    // Include the current number
    if (hasSum(nums, targetSize - 1, targetSum, index + 1, currentSum + nums[index])) {
        return true;
    }

    // Exclude the current number
    if (hasSum(nums, targetSize, targetSum, index + 1, currentSum)) {
        return true;
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Input cost array must not be null or empty");
    }

    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

