public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < Math.pow(2, k) + k - 1) {
        return false;
    }

    Set<String> uniqueSubstrings = new HashSet<>();

    for (int i = 0; i <= s.length() - k; i++) {
        uniqueSubstrings.add(s.substring(i, i + k));
    }

    return uniqueSubstrings.size() == Math.pow(2, k);
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }

    Set<String> seen = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        seen.add(s.substring(i, i + k));
    }

    return seen.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < (1 << k)) {
        return false;
    }

    boolean[] seen = new boolean[1 << k];
    int distinctCount = 0;
    int mask = (1 << k) - 1;
    int currentCode = 0;

    for (int i = 0; i < s.length(); i++) {
        currentCode = ((currentCode << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[currentCode]) {
                seen[currentCode] = true;
                distinctCount++;
                if (distinctCount == (1 << k)) {
                    return true;
                }
            }
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < Math.pow(2, k)) {
        return false;
    }

    boolean[] seen = new boolean[1 << k];
    int count = 0;
    int hash = 0;

    for (int i = 0; i < s.length(); i++) {
        if (i >= k) {
            hash -= (s.charAt(i - k) - '0') << (k - 1);
        }
        hash = ((hash << 1) | (s.charAt(i) - '0')) & ((1 << k) - 1);

        if (i >= k - 1 && !seen[hash]) {
            seen[hash] = true;
            count++;
            if (count == 1 << k) {
                return true;
            }
        }
    }

    return false;
}

