public int minInsertions(String s) {
    int leftBalance = 0;
    int rightBalance = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (rightBalance % 2 != 0) {
                insertions++;
                rightBalance--;
            }
            leftBalance++;
        } else {
            rightBalance++;
            if (leftBalance == 0) {
                insertions++;
            } else {
                leftBalance--;
            }
        }
    }

    return insertions + leftBalance * 2 + rightBalance;
}

public int minInsertions(String s) {
    if (s == null || s.length() == 0) {
