    int leftBalance = 0;
    int rightBalance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            leftBalance++;
            if (rightBalance > 0) {
                insertions++;
                rightBalance--;
            }
        } else if (c == ')') {
            rightBalance++;
            if (leftBalance == 0) {
                insertions++;
            } else {
                leftBalance--;
            }
        }
    }

    insertions += leftBalance * 2 + rightBalance * 2;

    return insertions;
}

