public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);

        if (ch == '(') {
            if (close % 2 != 0) {
                insertions++; // Insert a ')' to balance the previous open parenthesis
                close--;
            }
            open++;
        } else if (ch == ')') {
            close++;
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next character as we are handling a pair
            } else {
                insertions++; // Insert a '(' to balance the current close parenthesis
            }
        }
    }

    // Add remaining close parentheses as they need matching open parentheses
    insertions += open * 2 - close;

    return insertions;
}

public int minOperations(int n) {
    int minOperations = 0;

    // Calculate the target value that all elements should be equal to
    int target = n;

    // Calculate the sum of the first n odd numbers
    int sumOfOdds = n * n;

    // The minimum operations required is half the difference between the sum of odd numbers and the target value times n
    minOperations = sumOfOdds - target * n;

    return minOperations / 2;
}

