    }

    int maxSum = 0, currentSum = 0;

    // Calculate max subarray sum
    for (int num : nums) {
        currentSum = Math.max(num, currentSum + num);
        maxSum = Math.max(maxSum, currentSum);
    }

    currentSum = 0;

    // Calculate max subarray sum for negative numbers
