public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a'); // Initialize the array with 'a' to minimize the value
    k -= n; // Subtract the value of 'a' (1) for each character in the initial array

    int index = n - 1; // Start from the end of the array to maximize the position impact
    while (k > 0) {
        int add = Math.min(25, k); // We can add at most 25 to get the next lexicographically smallest character
        result[index] += add;
        k -= add;
        index--;
    }

    return new String(result);
}

