private static boolean isSteppingNumber(int num) {
        if(num < 10) {
            return true;
        }

        String numStr = String.valueOf(num);
        for(int i = 1; i < numStr.length(); i++) {
            int diff = Math.abs(numStr.charAt(i) - numStr.charAt(i - 1));
