private static boolean isSteppingNumber(int number) {
        if (number < 10) {
            return true;
        }
        int prevDigit = number % 10;
        number /= 10;
        while (number > 0) {
            int currentDigit = number % 10;
            if (Math.abs(prevDigit - currentDigit) != 1) {
                return false;
            }
            prevDigit = currentDigit;
            number /= 10;
        }
        return true;
    }

