private static void findSteppingNumbersHelper(int num, int low, int high, List<Integer> result) {
    if (num >= low && num <= high) {
        result.add(num);
    }
    if (num == 0 || num > high) {
        return;
    }
    int lastDigit = num % 10;
    if (lastDigit > 0) {
        findSteppingNumbersHelper(num * 10 + lastDigit - 1, low, high, result);
    }
    if (lastDigit < 9) {
        findSteppingNumbersHelper(num * 10 + lastDigit + 1, low, high, result);
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    Queue<Integer> queue = new LinkedList<>();

    if (low <= 9) {
        for (int i = 0; i <= 9; i++) {
            queue.add(i);
            if (i >= low && i <= high) {
                steppingNumbers.add(i);
            }
        }
    }

    while (!queue.isEmpty()) {
        int current = queue.poll();

        int lastDigit = current % 10;

        if (lastDigit != 0) {
            int next = current * 10 + lastDigit - 1;
            if (next > high) break;
            queue.add(next);
            if (next >= low && next <= high) {
                steppingNumbers.add(next);
            }
        }

        if (lastDigit != 9) {
            int next = current * 10 + lastDigit + 1;
            if (next > high) break;
            queue.add(next);
            if (next >= low && next <= high) {
                steppingNumbers.add(next);
            }
        }
    }

    steppingNumbers.sort(Integer::compareTo);
    return steppingNumbers;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) return result;

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < 10; i++) {
            if (i >= low && i <= high) {
                result.add(i);
            }
            if (i != 0) {
                queue.add(i);
            }
        }

        while (!queue.isEmpty()) {
            int num = queue.poll();
            int lastDigit = num % 10;
            if (lastDigit + 1 <= 9) {
                int next = num * 10 + (lastDigit + 1);
                if (next <= high) {
                    result.add(next);
                    queue.add(next);
                }
            }
            if (lastDigit - 1 >= 0) {
                int next = num * 10 + (lastDigit - 1);
                if (next <= high) {
                    result.add(next);
                    queue.add(next);
                }
            }
        }

        result.sort(Integer::compareTo);
        return result;
    }

public static int countDigitOne(int n) {
    int count = 0;
    for (long i = 1; i <= n; i *= 10) {
        long divider = i * 10;
        long curr = (n / divider) * i;
        long rest = n % divider;
        if (curr % i < i) {
            count += curr / i * i + Math.min(i, rest + 1);
        } else {
            count += curr / i * i + i;
        }
    }
    return count;
}

