public static int longestLine(final int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    // directions: right, down, down-right, down-left
    int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                for (int[] direction : directions) {
                    int len = 1;
                    int x = i + direction[0];
                    int y = j + direction[1];

                    while (x >= 0 && x < m && y >= 0 && y < n && mat[x][y] == 1) {
                        len++;
                        x += direction[0];
                        y += direction[1];
                    }

                    longest = Math.max(longest, len);
                }
            }
        }
    }

    return longest;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    // Arrays to store the lengths of consecutive 1s
    int[] horizontal = new int[n];
    int[] vertical = new int[m];
    int[] diagonal = new int[n];
    int[] antiDiagonal = new int[n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                horizontal[j] = j > 0 ? horizontal[j - 1] + 1 : 1;
                // Vertical
                vertical[i] = i > 0 ? vertical[i - 1] + 1 : 1;
                // Diagonal
                diagonal[j] = j > 0 && i > 0 ? diagonal[j - 1] + 1 : 1;
                // Anti-diagonal
                antiDiagonal[j] = j < n - 1 && i > 0 ? antiDiagonal[j + 1] + 1 : 1;

                // Update the longest line found
                longest = Math.max(longest, horizontal[j]);
                longest = Math.max(longest, vertical[i]);
                longest = Math.max(longest, diagonal[j]);
                longest = Math.max(longest, antiDiagonal[j]);
            } else {
                // Reset the counts if the current cell is 0
                horizontal[j] = 0;
                vertical[i] = 0;
                diagonal[j] = 0;
                antiDiagonal[j] = 0;
            }
        }
    }

    return longest;
}

