public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] count = new int[n];
    count[0] = 1;
    for (int i = 1; i < n; i++) {
        int sum = A[i - 1] + A[i];
        int sqrt = (int) Math.sqrt(sum);
        if (sqrt * sqrt == sum) {
            for (int j = i - 1; j >= 0; j--) {
                if (A[j] == A[i]) {
                    count[i] += count[j];
                }
            }
        }
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += count[i];
    }
    return result;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    boolean[] used = new boolean[n];
    int result = 0;

    backtrack(0, A, used, result);

    return result;
}

private static void backtrack(int start, int[] A, boolean[] used, int[] result) {
    if (start == A.length) {
        result[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i] || (start > 0 && !isPerfectSquare(A[start - 1] + A[i]))) {
            continue;
        }

        used[i] = true;
        backtrack(start + 1, A, used, result);
        used[i] = false;
    }
}

private static boolean isPerfectSquare(int num) {
    if (num < 0) return false;

    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    boolean[] used = new boolean[n];
    List<List<Integer>> result = new ArrayList<>();
    solve(A, 0, new ArrayList<>(), used, result);
    return result.size();
}

private static void solve(int[] A, int index, List<Integer> path, boolean[] used, List<List<Integer>> result) {
    if (index == A.length) {
        result.add(new ArrayList<>(path));
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            used[i] = true;
            path.add(A[i]);
            if (path.size() > 1 && !isPerfectSquare(path.get(path.size() - 2) + A[i])) {
                path.remove(path.size() - 1);
                used[i] = false;
                continue;
            }
            solve(A, index + 1, path, used, result);
            path.remove(path.size() - 1);
            used[i] = false;
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            return 0;
        }

        Map<Integer, Set<Integer>> graph = new HashMap<>();
        Set<Integer> squares = new HashSet<>();

        // Precompute all perfect squares up to the maximum possible sum of two elements
        int maxSum = 0;
        for (int i = 0; i < A; i++) {
            for (int j = i; j < A; j++) {
                int sum = A[i] + A[j];
                int root = (int) Math.sqrt(sum);
                if (root * root == sum) {
                    squares.add(sum);
                    graph.computeIfAbsent(A[i], s -> new HashSet<>()).add(A[j]);
                    graph.computeIfAbsent(A[j], s -> new HashSet<>()).add(A[i]);
                }
                maxSum = Math.max(maxSum, sum);
            }
        }

        int[] dp = new int[1 << A.length];
        for (int i = 1; i < (1 << A.length); i++) {
            for (int next = 0; next < A.length; next++) {
                if ((i & (1 << next)) != 0) {
                    int prev = i - (1 << next);
                    if (prev == 0 || graph.containsKey(A[next]) && graph.get(A[next]).contains(A[prev & ((1 << A.length) - 1)])) {
                        dp[i] += dp[prev];
                    }
                }
            }
        }

        return dp[(1 << A.length) - 1];
    }

public static int squarePermutations(int[] A) {
    if (A == null || A.length < 2) {
        return 0;
    }

    int[] count = new int[1];
    backtrack(A, 0, count);
    return count[0];
}

private static void backtrack(int[] A, int start, int[] count) {
    if (start == A.length - 1) {
        count[0]++;
        return;
    }

    for (int i = start; i < A.length; i++) {
        swap(A, start, i);
        if (isPerfectSquare(A[start] + A[start + 1])) {
            backtrack(A, start + 1, count);
        }
        swap(A, start, i); // backtrack
    }
}

private static boolean isPerfectSquare(int x) {
    int s = (int) Math.sqrt(x);
    return s * s == x;
}

private static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}

