public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i;
    // Find the first digit that is smaller than the digit next to it.
    for (i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }
    // If no such digit is found, return -1.
    if (i == -1) {
        return -1;
    }
    // Find the smallest digit on the right side of digits[i] but larger than digits[i].
    int j;
    for (j = digits.length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }
    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Sort the digits after the position i
    Arrays.sort(digits, i + 1, digits.length);
    // Convert the array back to integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

