public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    backtrack(result, new char[n], 0, n - 1);
    return result;
}

private static void backtrack(List<String> result, char[] current, int left, int right) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    char[] symmetricPairs = {'0', '1', '6', '8', '9'};
    for (int i = 0; i < symmetricPairs.length; i++) {
        if (left == right && symmetricPairs[i] != symmetricPairs[i] && symmetricPairs[i] != '0') {
            continue; // Skip '0' for single-digit numbers and symmetric pairs that are not valid center symmetric numbers
        }
        current[left] = symmetricPairs[i];
        if (left != right) {
            current[right] = symmetricPairs[i] == '6' ? '9' : (symmetricPairs[i] == '9' ? '6' : symmetricPairs[i]);
        }
        backtrack(result, current, left + 1, right - 1);
    }
}

public static List<String> centerSymmetricNumbers(int n) {
