private static List<String> centerSymmetricNumbersHelper(int n, int m, char[] current) {
    List<String> result = new ArrayList<>();
    if (n == 0) {
        result.add(new String(current));
    } else if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
    } else {
        for (char c : new char[]{'0', '1', '6', '8', '9'}) {
            if (m == n) {
                if (c == '0') continue;
            }
            current[(n - m) / 2] = c;
            current[(n + m - 1) / 2] = getComplement(c);
            result.addAll(centerSymmetricNumbersHelper(n - 2, m - 2, current));
        }
    }
    return result;
}

private static char getComplement(char c) {
    switch (c) {
        case '6':
            return '9';
        case '9':
            return '6';
        case '0':
            return '0';
        case '1':
            return '1';
        case '8':
            return '8';
        default:
            throw new IllegalArgumentException("Invalid character");
    }
}

