private static void helper(List<String> result, char[] chars, int left, int right) {
    if (left > right) {
        result.add(new String(chars));
        return;
    }
    if (left == right) {
        if (chars[left] != '0') {
            result.add(new String(chars));
        }
        return;
    }
    char[] symmetricPairs = {'0', '1', '8', '6', '9'};
    for (char c : symmetricPairs) {
        if (left == 0 && c == '0') {
            continue;
        }
        if (c == '6') {
            chars[left] = c;
            chars[right] = '9';
        } else if (c == '9') {
            chars[left] = c;
            chars[right] = '6';
        } else {
            chars[left] = c;
            chars[right] = c;
        }
        helper(result, chars, left + 1, right - 1);
    }
}

