private static void helper(List<String> result, String current, int left, int right) {
    if (left < right) {
        addSymmetricPairs(result, current, "69");
        addSymmetricPairs(result, current, "88");
        addSymmetricPairs(result, current, "96");
        addSymmetricPairs(result, current, "11");
    } else if (left == right) {
        if (left == 1) {
            result.add("0");
        }
        addSymmetricPairs(result, current, "11");
        addSymmetricPairs(result, current, "88");
    }
}

private static void addSymmetricPairs(List<String> result, String current, String pair) {
