public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // Create an array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];

    // Fill the array with a large number (infinity), except for the base case
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }

    // Zero can be represented by zero perfect squares
    dp[0] = 0;

    // Iterate through each number from 1 to n
    for (int i = 1; i <= n; i++) {
        // Check each perfect square smaller than or equal to i
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // Return the minimum number of perfect squares for n
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Maximum squares are the number itself (1^2 + 1^2 + ...)
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

